func isListedInSoftwareverzeichnis(repositoryID int64) (bool, error) {
	apiURL := config.RuntimeConfig.SubsequentUseAPIDomain
	if apiURL == "" {
		return false, nil
	}
	apiURL, err := url.JoinPath(apiURL, fmt.Sprintf("/api/v1/search/%d", repositoryID))
	if err != nil {
		slog.Error("failed to create API URL", "err", err, "repositoryID", repositoryID)
		return false, err
	}

	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()

	// just call the url and check if the response is okish
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, apiURL, nil)
	if err != nil {
		slog.Error("failed to create request", "err", err, "repositoryID", repositoryID)
		return false, err
	}

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		slog.Error("failed to call API", "err", err, "repositoryID", repositoryID)
		return false, err
	}
	defer resp.Body.Close()

	if resp.StatusCode == http.StatusOK {
		return true, nil
	}

	if resp.StatusCode == http.StatusNotFound {
		return false, nil
	}
	return false, fmt.Errorf("unexpected status code: %d", resp.StatusCode)
}

func extractConcurrencyFromEnv() int {
	concurrency := os.Getenv("PARALLEL_PROJECTS_CONCURRENCY")
	var concurrencyInt = 10 // limit concurrency to 10 by default
	if concurrency != "" {
		tmp, err := strconv.Atoi(concurrency)
		if err == nil {
			concurrencyInt = tmp
		}
	}
	slog.Info("setting concurrency for processing projects", "concurrency", concurrencyInt)

	return concurrencyInt
}

